"""Prepare local-only Prototypes appearance markup from a pinned review."""
import json,re,hashlib,sys
from pathlib import Path
src=Path(sys.argv[1]);dest=Path(sys.argv[2]);assert not dest.exists();x=json.loads(src.read_text());assert x['archive_sha256']=='a624dfda8f09d80faeb3af744e0f601e99eeddd99eec5e465136ba519f306456';v=x['records']['Prototypes'];raw=v['raw_wikitext'];assert v['revision_id']=='14740158' and hashlib.sha256(raw.encode()).hexdigest()=='ef411f5ca872a899cfb46c904a44bac0f661fc9526b913338e1223685231a75c';hs=list(re.finditer(r'(?m)^\s*(={2,6})\s*(.*?)\s*\1\s*$',raw));i,h=next((i,h) for i,h in enumerate(hs) if h.group(2).strip().casefold()=='appearances');end=next((z.start() for z in hs[i+1:] if len(z.group(1))<=len(h.group(1))),len(raw));section=raw[h.end():end].strip();rec={'work_id':'visionaries-prototypes','title':'Prototypes','revision_id':v['revision_id'],'timestamp':v['timestamp'],'sections':[{'raw_wikitext':section,'sha256':hashlib.sha256(section.encode()).hexdigest()}]};dest.write_text(json.dumps({'source_archive_sha256':x['archive_sha256'],'target_count':1,'not_found':[],'records':{'Prototypes':rec}},ensure_ascii=False));dest.chmod(0o600);print('Prepared pinned local-only Prototypes appearance section')
